1	/**
2	 * The DNA swatch tokens, mirrored from `--color-dna-*` in `app/globals.css`.
3	 *
4	 * Kept as one named set so the profile hub and the Style DNA card cannot drift
5	 * apart — a second hard-coded palette somewhere else is exactly how two screens
6	 * end up disagreeing about what an archetype looks like.
7	 */
8	const DNA = {
9	  cream: "#ede6d8",
10	  navy: "#2c3a4c",
11	  camel: "#b89a6a",
12	  olive: "#6e6f52",
13	  rust: "#b86a47",
14	} as const;
15	
16	/** The four archetypes the onboarding quiz can produce (`lib/onboarding/questions.ts`). */
17	const PALETTES: Record<string, string[]> = {
18	  "Old Money": [DNA.cream, DNA.navy, DNA.camel],
19	  "Smart Casual": [DNA.camel, DNA.olive, DNA.cream],
20	  Preppy: [DNA.navy, DNA.cream, DNA.rust],
21	  Streetwear: [DNA.olive, DNA.navy, DNA.rust],
22	};
23	
24	/** The full set, for a profile that has not answered the quiz. */
25	const FALLBACK = Object.values(DNA);
26	
27	/**
28	 * One or two letters for the avatar circle.
29	 *
30	 * Falls back to the email rather than rendering an empty circle, which reads as
31	 * a broken image rather than as a person.
32	 */
33	export function initials(name: string | null, email: string): string {
34	  const words = (name ?? "").trim().split(/\s+/).filter(Boolean);
35	  if (words.length > 0) {
36	    return words
37	      .slice(0, 2)
38	      .map((w) => w[0]!.toUpperCase())
39	      .join("");
40	  }
41	  const first = email.replace(/[^a-z0-9]/gi, "")[0];
42	  return (first ?? "F").toUpperCase();
43	}
44	
45	/**
46	 * A display handle derived from the email's local-part.
47	 *
48	 * `profiles` has no `handle` column and adding one needs an edit flow and a
49	 * uniqueness rule, which belong with the Settings account row rather than here.
50	 * Isolated in this one function so replacing it later is a one-line change.
51	 *
52	 * Plus-addressing and dots are stripped: `first.last+fitcheck@…` reading as
53	 * `@first.last+fitcheck` looks like a bug, and the suffix leaks that the address
54	 * was tagged.
55	 */
56	export function handleFrom(email: string): string {
57	  const local = email.split("@")[0] ?? "";
58	  const cleaned = local.split("+")[0]!.replace(/[^a-z0-9_]/gi, "").toLowerCase();
59	  return `@${cleaned || "fitcheck"}`;
60	}
61	
62	/** Swatches for an archetype; the full DNA set when there is no answer yet. */
63	export function paletteFor(archetype: string | null): string[] {
64	  if (!archetype) return FALLBACK;
65	  return PALETTES[archetype] ?? FALLBACK;
66	}
