1	/**
2	 * The user's local calendar date, as `YYYY-MM-DD`.
3	 *
4	 * This is the key of the daily look set. It must be LOCAL: keyed on the UTC
5	 * date, the drop would roll over mid-evening for eastern users and mid-morning
6	 * for western ones. `en-CA` is used purely because it formats as YYYY-MM-DD.
7	 */
8	export function localDateFor(now: Date, timeZone: string): string {
9	  try {
10	    return new Intl.DateTimeFormat("en-CA", {
11	      timeZone,
12	      year: "numeric",
13	      month: "2-digit",
14	      day: "2-digit",
15	    }).format(now);
16	  } catch {
17	    // An unknown zone must never block generation — fall back to UTC.
18	    return now.toISOString().slice(0, 10);
19	  }
20	}
21

1	function shiftDay(date: string, delta: number): string {
2	  const d = new Date(`${date}T00:00:00Z`);
3	  d.setUTCDate(d.getUTCDate() + delta);
4	  return d.toISOString().slice(0, 10);
5	}
6	
7	/**
8	 * Consecutive days with at least one wear, counting back from today.
9	 *
10	 * A streak ending YESTERDAY still counts. Anchoring strictly on today would
11	 * show every user a zero every morning until they dressed, which reads as
12	 * "you lost your streak" rather than "the day is young".
13	 *
14	 * Counting always starts at today even when the diary is showing an older
15	 * month — a streak that changed as you paged backwards would be measuring the
16	 * view rather than the habit.
17	 *
18	 * Dates are UTC-shifted only for arithmetic; the values themselves are the
19	 * user's local date keys, so no timezone conversion happens here.
20	 */
21	export function currentStreak(dates: string[], today: string): number {
22	  const set = new Set(dates);
23	  let cursor = set.has(today) ? today : shiftDay(today, -1);
24	  if (!set.has(cursor)) return 0;
25	
26	  let n = 0;
27	  while (set.has(cursor)) {
28	    n++;
29	    cursor = shiftDay(cursor, -1);
30	  }
31	  return n;
32	}
